import AppKit
import Domain
import Testing

@testable import TextInsertion

/// Runs against a pasteboard of its own, so the tests never touch the user's clipboard.
@MainActor
@Suite("NSPasteboard adapter", .timeLimit(.minutes(1)))
struct NSPasteboardAdapterTests {
    private static let sourceBundleID = "dev.example.source"
    private static let markerTypes: Set<String> = [
        "org.nspasteboard.TransientType",
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.AutoGeneratedType",
        "org.nspasteboard.source",
    ]
    private static let rtf = Data("{\\rtf1 rich}".utf8)
    private static let png = Data([0x89, 0x50, 0x4E, 0x47])
    private static let custom = Data([0x01, 0x02, 0x03])
    private static let customType = "dev.example.custom-type"

    private let pasteboard = NSPasteboard(name: NSPasteboard.Name("susurro-test-\(UUID().uuidString)"))

    private func makeAdapter(limits: SnapshotLimits = .standard) -> NSPasteboardAdapter {
        NSPasteboardAdapter(pasteboard: pasteboard, sourceBundleID: Self.sourceBundleID, limits: limits)
    }

    /// Two items, as a copied rich selection leaves them, the first with a type of an app's own.
    private func putRichContent() {
        pasteboard.clearContents()
        let first = NSPasteboardItem()
        first.setString("alpha", forType: .string)
        first.setData(Self.rtf, forType: .rtf)
        first.setData(Self.png, forType: .png)
        first.setData(Self.custom, forType: NSPasteboard.PasteboardType(Self.customType))
        let second = NSPasteboardItem()
        second.setString("beta", forType: .string)
        _ = pasteboard.writeObjects([first, second])
    }

    /// Every item with its types and the data of each. Reading a promised type counts as a read.
    private func contents() -> [[PasteboardEntry]] {
        (pasteboard.pasteboardItems ?? []).map { item in
            item.types.compactMap { type in
                item.data(forType: type).map { PasteboardEntry(type: type.rawValue, data: $0) }
            }
        }
    }

    private func declaredTypes() -> Set<String> {
        Set(pasteboard.pasteboardItems?.first?.types.map(\.rawValue) ?? [])
    }

    // MARK: Snapshot

    @Test("a snapshot holds every item and every type, custom ones included, and a restore reproduces them")
    func richPasteboardRoundTrip() async throws {
        putRichContent()
        let before = contents()
        #expect(before.count == 2)
        let adapter = makeAdapter()

        let snapshot = await adapter.snapshot()
        try adapter.writeConcrete("dictated")
        try adapter.restore(snapshot)

        #expect(snapshot.isFaithful)
        #expect(snapshot.items.count == 2)
        #expect(snapshot.items[0].first { $0.type == Self.customType }?.data == Self.custom)
        #expect(snapshot.items[0].first { $0.type == NSPasteboard.PasteboardType.rtf.rawValue }?.data == Self.rtf)
        #expect(contents() == before)
    }

    @Test("an empty pasteboard is empty again after a restore")
    func emptyPasteboard() async throws {
        pasteboard.clearContents()
        let adapter = makeAdapter()

        let snapshot = await adapter.snapshot()
        try adapter.writeConcrete("dictated")
        try adapter.restore(snapshot)

        #expect(snapshot.items.isEmpty)
        #expect(contents().isEmpty)
    }

    @Test("a snapshot over the size limit stops there and says it is too large")
    func tooLarge() async {
        putRichContent()
        let adapter = makeAdapter(limits: SnapshotLimits(maxBytes: 4, maxDuration: .seconds(30)))

        let snapshot = await adapter.snapshot()

        #expect(snapshot.gap == .tooLarge)
        #expect(!snapshot.isFaithful)
    }

    @Test("a snapshot that takes longer than its limit stops there and says it is too slow")
    func tooSlow() async {
        putRichContent()
        let adapter = makeAdapter(limits: SnapshotLimits(maxBytes: .max, maxDuration: .zero))

        let snapshot = await adapter.snapshot()

        #expect(snapshot.gap == .tooSlow)
    }

    /// An owner that has nothing to give for a type it declared, as an app whose lazily provided data is gone.
    private final class EmptyProvider: NSObject, NSPasteboardItemDataProvider {
        func pasteboard(
            _ pasteboard: NSPasteboard?, item: NSPasteboardItem, provideDataForType type: NSPasteboard.PasteboardType
        ) {}
    }

    @Test("a type that gives no data is a gap, because a restore would lose it")
    func typeWithoutData() async {
        pasteboard.clearContents()
        let provider = EmptyProvider()
        let item = NSPasteboardItem()
        item.setString("kept", forType: .string)
        item.setDataProvider(provider, forTypes: [NSPasteboard.PasteboardType(Self.customType)])
        _ = pasteboard.writeObjects([item])

        let snapshot = await makeAdapter().snapshot()

        #expect(snapshot.gap == .typeWithoutData)
        #expect(snapshot.items.first?.contains { $0.type == NSPasteboard.PasteboardType.string.rawValue } == true)
        withExtendedLifetime(provider) {}
    }

    // MARK: Promise

    @Test("the promise declares the markers and supplies the text lazily, and a request for it is a receipt")
    func promiseUnderMarkers() throws {
        putRichContent()
        let adapter = makeAdapter()

        let receipts = try adapter.publishPromise("hello world")

        #expect(declaredTypes() == Self.markerTypes.union(["public.utf8-plain-text"]))
        #expect(pasteboard.pasteboardItems?.count == 1)
        #expect(pasteboard.pasteboardItems?.first?.string(forType: .sourceApp) == Self.sourceBundleID)
        #expect(receipts.count == 0)

        #expect(pasteboard.string(forType: .string) == "hello world")
        #expect(receipts.count == 1)
    }

    @Test("publishing the promise changes the change count, and a read of it does not")
    func changeCounts() throws {
        let adapter = makeAdapter()
        let before = adapter.changeCount

        _ = try adapter.publishPromise("hello world")
        let published = adapter.changeCount
        _ = pasteboard.string(forType: .string)

        #expect(published > before)
        #expect(adapter.changeCount == published)
    }

    @Test("concrete text carries the markers and has nothing promised")
    func concreteText() throws {
        putRichContent()
        let adapter = makeAdapter()

        try adapter.writeConcrete("hello world")

        #expect(declaredTypes() == Self.markerTypes.union(["public.utf8-plain-text"]))
        #expect(pasteboard.pasteboardItems?.count == 1)
        #expect(pasteboard.string(forType: .string) == "hello world")
    }

    @Test("a promise that was replaced by concrete text still reads as the text, and no longer asks the owner")
    func replacedPromise() throws {
        let adapter = makeAdapter()
        let receipts = try adapter.publishPromise("hello world")

        try adapter.writeConcrete("hello world")
        #expect(pasteboard.string(forType: .string) == "hello world")

        #expect(receipts.count == 0)
    }
}
